# Convert the minimized expression to a shallow AND/OR/NOT circuit.
# Negated literals are handled directly as affine complements, so they
# require no gate of their own.
nodes = []
def add(op, args):
    # Share identical subexpressions.
    key = (op, tuple(args))
    for i, n in enumerate(nodes):
        if n["key"] == key:
            return ("g", i)
    i = len(nodes)
    nodes.append({"op": op, "args": tuple(args), "key": key})
    return ("g", i)

