    if e.func == Not:
        a = cv(e.args[0])
        if a[0] == "x":
            return ("lit", a, 1)
        if a[0] == "c":
            return ("c", 1-a[1])
        return add("not", (a,))
    if e.func in (And, Or):
        args = [cv(a) for a in e.args]
        op = "and" if e.func == And else "or"
        while len(args) > 2:
            args = [add(op, (args[0], args[1]))] + args[2:]
