from sympy import symbols
from sympy.logic.boolalg import (
    SOPform, POSform, simplify_logic, to_anf, And, Or, Not, Xor,
    BooleanTrue, BooleanFalse
)
import json

spec = TASK["public"]["specification"]
xs = symbols("x0:10")
ones = [i for i, y in enumerate(spec["outputs"]) if y == 1]
candidates = [
    SOPform(xs, ones),
    POSform(xs, ones),
    simplify_logic(SOPform(xs, ones), force=True),
    simplify_logic(POSform(xs, ones), force=True),
    to_anf(SOPform(xs, ones)),
]

def compile_expr(expr):
    nodes = []
    def add(op, args):
        key = (op, tuple(args))
        for i, n in enumerate(nodes):
            if n["key"] == key:
                return ("g", i)
        i = len(nodes)
        nodes.append({"op": op, "args": tuple(args), "key": key})
        return ("g", i)

    def cv(e):
        if e in xs:
            return ("x", xs.index(e))
        if e == BooleanTrue:
            return ("c", 1)
        if e == BooleanFalse:
            return ("c", 0)
        if e.func == Not:
            a = cv(e.args[0])
            if a[0] == "x":
                return ("lit", a, 1)
            if a[0] == "c":
                return ("c", 1-a[1])
            return add("not", (a,))
        if e.func in (And, Or, Xor):
            args = [cv(a) for a in e.args]
            if e.func == Xor:
                z = args[0]
                for a in args[1:]:
                    both = add("and", (z, a))
                    either = add("or", (z, a))
                    z = add("and", (either, add("not", (both,))))
                return z
            op = "and" if e.func == And else "or"
            while len(args) > 2:
                args = [add(op, (args[0], args[1]))] + args[2:]
            return add(op, tuple(args)) if len(args) == 2 else args[0]
        raise ValueError("Unsupported expression: " + str(e))

    root = cv(expr)
    def dep(v):
        return 0 if v[0] != "g" else 1 + max(dep(a) for a in nodes[v[1]]["args"])
    levels = {i: 1 + max(dep(a) for a in n["args"]) for i, n in enumerate(nodes)}
    counts = [sum(levels[i] == d for i in levels) for d in range(1, 5)]
    fits = max(levels.values(), default=0) <= 4 and max(counts, default=0) <= 8
    return nodes, root, levels, counts, fits

compiled = [compile_expr(e) for e in candidates]
valid = [c for c in compiled if c[4]]
if not valid:
    raise ValueError("SOP/POS/ANF minimizations do not fit the four-stage, eight-signal layout")
nodes, root, levels, counts, _ = min(valid, key=lambda c: (sum(c[3]), max(c[3], default=0)))

