slots = {i: 10 + 3*slot for d in range(1, 5) for slot, i in enumerate(by_level[d])}

patch = []
def put(tensor, index, value):
    if value:
        patch.append({"op": "set", "tensor": tensor, "index": index, "value": float(value)})

# A Boolean signal is represented as h[k] - h[k+2].
def terms(v):
    if v[0] == "x":
        return 0, {v[1]: 1}
    if v[0] == "c":
        return v[1], {}
    if v[0] == "lit":
        off, coeff = terms(v[1])
        return 1-off, {k: -a for k, a in coeff.items()}
    k = slots[v[1]]
    return 0, {k: 1, k+2: -1}

for layer in range(4):
    tensor = f"w{layer}"
    if layer == 0:
        for i in range(10):
            put(tensor, [i, i], 1)
    else:
        for i in range(10):
            put(tensor, [i, i], 1)

    for slot, ni in enumerate(by_level[layer+1]):
        n = nodes[ni]
        row = slots[ni]
        const = -1 if n["op"] == "and" else (1 if n["op"] == "not" else 0)
        args = [(n["args"][0], -1)] if n["op"] == "not" else [(a, 1) for a in n["args"]]
        coeffs = {}
        for v, factor in args:
            off, cc = terms(v)
            const += factor * off
            for ch, value in cc.items():
                coeffs[ch] = coeffs.get(ch, 0) + factor * value
        for ch, value in coeffs.items():
            put(tensor, [row, ch], value)
            put(tensor, [row+2, ch], value)
        put(f"b{layer}", [row], const)
        put(f"b{layer}", [row+2], const-1)

off, coeffs = terms(root)
if off:
    put("bias", [1], off)
for ch, value in coeffs.items():
    put("out", [1, ch], value)

