import random, json
from sympy import symbols

spec = TASK["public"]["specification"]
ys = spec["outputs"]
xs = symbols("x0:10")
nodes = []

def inv(a):
    if a[0] == "c":
        return ("c", 1-a[1])
    if a[0] == "lit":
        return a[1]
    return ("lit", a)

def gate(op, a, b=None):
    if op == "not":
        return inv(a)
    if op in ("and", "or"):
        if op == "and":
            if a == ("c", 0) or b == ("c", 0): return ("c", 0)
            if a == ("c", 1): return b
            if b == ("c", 1): return a
            if a == b: return a
        else:
            if a == ("c", 1) or b == ("c", 1): return ("c", 1)
            if a == ("c", 0): return b
            if b == ("c", 0): return a
            if a == b: return a
        if str(a) > str(b):
            a, b = b, a
        key = (op, a, b)
        for i, n in enumerate(nodes):
            if n["key"] == key:
                return ("g", i)
        i = len(nodes)
        nodes.append({"op": op, "args": (a, b), "key": key})
        return ("g", i)
    raise ValueError(op)

def mux(c, hi, lo):
    if hi == lo: return hi
    if hi == ("c", 1) and lo == ("c", 0): return c
    if hi == ("c", 0) and lo == ("c", 1): return inv(c)
    if lo == ("c", 0): return gate("and", c, hi)
    if hi == ("c", 0): return gate("and", inv(c), lo)
    if lo == ("c", 1): return gate("or", inv(c), hi)
    if hi == ("c", 1): return gate("or", c, lo)
    return gate("or", gate("and", c, hi), gate("and", inv(c), lo))

def build(order):
    global nodes
    nodes = []
    memo = {}
    def rec(indices, pos):
        vals = {ys[i] for i in indices}
        if len(vals) == 1:
            return ("c", vals.pop())
        key = (pos, tuple(indices))
        if key in memo: return memo[key]
        bit = 1 << (9-order[pos])
        lo = [i for i in indices if not (i & bit)]
        hi = [i for i in indices if i & bit]
        result = mux(("x", order[pos]), rec(hi, pos+1), rec(lo, pos+1))
        memo[key] = result
        return result
    root = rec(list(range(1024)), 0)
    def dep(v):
        return 0 if v[0] != "g" else 1 + max(dep(a) for a in nodes[v[1]]["args"])
    levels = {i: 1 + max(dep(a) for a in n["args"]) for i, n in enumerate(nodes)}
    counts = [sum(levels[i] == d for i in levels) for d in range(1, 5)]
    fits = max(levels.values(), default=0) <= 4 and max(counts, default=0) <= 8
    return nodes, root, levels, counts, fits

rng = random.Random(20)
orders = [tuple(range(10))]
for _ in range(500):
    order = list(range(10))
    rng.shuffle(order)
    orders.append(tuple(order))

best = None
for order in orders:
    candidate = build(order)
    if candidate[4]:
        if best is None or sum(candidate[3]) < sum(best[3]):
            best = candidate
if best is None:
    raise ValueError("No four-stage, eight-signal implementation found; increase the variable-order trials")

nodes, root, levels, counts, _ = best
by_level = {d: [i for i in range(len(nodes)) if levels[i] == d] for d in range(1, 5)}
slots = {i: 10 + 3*slot for d in range(1, 5) for slot, i in enumerate(by_level[d])}

def affine(v):
    if v[0] == "x": return 0, {v[1]: 1}
    if v[0] == "c": return v[1], {}
    if v[0] == "lit":
        off, cc = affine(v[1])
        return 1-off, {ch: -val for ch, val in cc.items()}
    ch = slots[v[1]]
    return 0, {ch: 1, ch+2: -1}

patch = []
def put(tensor, index, value):
    if value:
        patch.append({"op": "set", "tensor": tensor, "index": index, "value": float(value)})

for layer in range(4):
    tensor = f"w{layer}"
    for i in range(10):
        put(tensor, [i, i], 1)
    for ni in by_level[layer+1]:
        n = nodes[ni]
        row = slots[ni]
        a, b = n["args"]
        const = -1 if n["op"] == "and" else 0
        coeffs = {}
        for v in (a, b):
            off, cc = affine(v)
            const += off
            for ch, val in cc.items():
                coeffs[ch] = coeffs.get(ch, 0) + val
        for ch, val in coeffs.items():
            put(tensor, [row, ch], val)
            put(tensor, [row+2, ch], val)
        put(f"b{layer}", [row], const)
        put(f"b{layer}", [row+2], const-1)

off, coeffs = affine(root)
if off:
    put("bias", [1], off)
for ch, val in coeffs.items():
    put("out", [1, ch], val)

sub = {"patch": patch}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
